import{c as a,$ as s,Q as n,j as i,m as t,h as d,ax as r,n as c,o as l,S as p}from"./chunks/framework.DGHXLY8X.js";const b=JSON.parse('{"title":"Pipeline model","description":"","frontmatter":{},"headers":[],"relativePath":"reference/pipeline-model.md","filePath":"reference/pipeline-model.md","lastUpdated":1779947889000}'),h={name:"reference/pipeline-model.md"};function m(u,e,g,f,y,A){const o=s("Mermaid");return n(),i("div",null,[e[1]||(e[1]=t('<h1 id="pipeline-model" tabindex="-1">Pipeline model <a class="header-anchor" href="#pipeline-model" aria-label="Permalink to &quot;Pipeline model&quot;">​</a></h1><p>This page explains <em>why</em> VideoNode organises its runtime around three independent entities and what the lifecycle rules mean in practice. State is managed via the UI or <a href="./rest-api">REST API</a>; you should not need to read or edit the daemon&#39;s on-disk format directly.</p><h2 id="three-independent-entities" tabindex="-1">Three independent entities <a class="header-anchor" href="#three-independent-entities" aria-label="Permalink to &quot;Three independent entities&quot;">​</a></h2><p>Sources, composers, and streams are top-level objects with separate identities and CRUD surfaces. They reference each other by explicit string (<code>&quot;source:&lt;id&gt;&quot;</code> or <code>&quot;composer:&lt;id&gt;&quot;</code>), not by containment. This separation means you can add or remove streams without touching a source, and rearrange a composer layout without restarting an encoder.</p><ul><li><strong>Source</strong>: one <code>videonode-source</code> process per source, capturing V4L2 frames (or emitting a test pattern) and broadcasting NV12 dma-bufs to N consumers over SCM_RIGHTS sockets.</li><li><strong>Composer</strong>: one <code>videonode-composer</code> process per composer, reading N source sockets, compositing onto a BGRA canvas via OpenGL ES, and broadcasting the result.</li><li><strong>Stream</strong>: one <code>vn-sink | ffmpeg</code> encoder per stream, dialing an upstream source or composer socket and publishing to RTSP, SRT, or WebRTC.</li></ul><h2 id="pipeline-gated-lifecycle-sources-and-composers" tabindex="-1">Pipeline-gated lifecycle (sources and composers) <a class="header-anchor" href="#pipeline-gated-lifecycle-sources-and-composers" aria-label="Permalink to &quot;Pipeline-gated lifecycle (sources and composers)&quot;">​</a></h2><p>Sources and composers are <strong>pipeline-gated</strong>: they run while the daemon-wide pipeline switch is on and stop when it is off. The switch is a single toggle in the UI (or <code>POST /api/pipeline/start</code> / <code>POST /api/pipeline/stop</code>). CRUD operations (creating, patching, or deleting entities) work regardless of switch state and persist immediately; on the next pipeline start, everything rehydrates from the store.</p><p>While the pipeline is on, sources and composers stay up until you delete them. Streams attaching or detaching do not restart them.</p><h2 id="lazy-encoder-on-reader-lifecycle-streams" tabindex="-1">Lazy-encoder-on-reader lifecycle (streams) <a class="header-anchor" href="#lazy-encoder-on-reader-lifecycle-streams" aria-label="Permalink to &quot;Lazy-encoder-on-reader lifecycle (streams)&quot;">​</a></h2><p>Streams exist as a persistent <strong>plan</strong>, but the actual <code>vn-sink | ffmpeg</code> encoder process only runs when someone is watching. When the first reader (RTSP client, SRT listener, WebRTC peer) connects, the daemon calls <code>Pipeline.EnsureEncoder</code> and the encoder spawns. When the last reader disconnects, a 2-second debounce fires (<code>lastReaderDebounce = 2 * time.Second</code> in <code>internal/streaming/server.go</code>) and the encoder stops. A reader reconnecting within that window cancels the timer and the encoder stays warm.</p><p>This is deliberate: a hardware H.264 encoder slot and a V4L2 capture session are finite resources on an SBC. Holding them open for zero viewers wastes memory and device bandwidth.</p>',11)),(n(),d(p,null,{default:r(()=>[l(o,{id:"mermaid-48",class:"mermaid",graph:"stateDiagram-v2%0A%20%20direction%20TB%0A%20%20accTitle%3A%20Stream%20encoder%20lifecycle%0A%20%20accDescr%20%7B%0A%20%20%20%20Encoder%20plan%20is%20always%20resident.%20The%20encoder%20process%20only%20runs%0A%20%20%20%20while%20at%20least%20one%20reader%20is%20connected%3B%20a%202-second%20debounce%0A%20%20%20%20prevents%20thrash%20on%20rapid%20connect%2Fdisconnect.%0A%20%20%7D%0A%0A%20%20Idle%3A%20Idle%5Cn(plan%20resident%2C%5Cnencoder%20not%20running)%0A%20%20Running%3A%20Running%5Cn(encoder%20spawned%2C%5Cn1%2B%20readers)%0A%20%20Cooling%3A%20Cooling%20down%5Cn(last%20reader%20gone%2C%5Cn2%20s%20timer%20armed)%0A%0A%20%20%5B*%5D%20--%3E%20Idle%0A%20%20Idle%20--%3E%20Running%3A%20first%20reader%3Cbr%2F%3Econnects%0A%20%20Running%20--%3E%20Cooling%3A%20last%20reader%3Cbr%2F%3Edisconnects%0A%20%20Cooling%20--%3E%20Idle%3A%202%20s%20elapses%0A%20%20Cooling%20--%3E%20Running%3A%20reader%20reconnects%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<h2 id="reference-integrity" tabindex="-1">Reference integrity <a class="header-anchor" href="#reference-integrity" aria-label="Permalink to &quot;Reference integrity&quot;">​</a></h2><p>The three entities form a directed graph: streams point at composers or sources; composers point at sources. The API enforces that you cannot break a live reference:</p><ul><li>Deleting a source fails with a structured error listing every composer input and stream upstream that still names it.</li><li>Deleting a composer fails listing every stream that names it.</li><li>Deleting a stream has no upstream constraint; the source and composer stay running.</li></ul><p>This means tear-down order is always <strong>streams first, then composers, then sources</strong>.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p>All state is managed through the UI or the <a href="./../reference/rest-api">REST API</a>. The <code>streams.toml</code> file is the daemon&#39;s backing store; the UI and API rewrite it on every change. You should not need to edit it by hand.</p>',6))])}const w=a(h,[["render",m]]);export{b as __pageData,w as default};
